<?php
require_once 'config/db.php';require_once 'includes/auth.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='cancel'){
 $stmt=$pdo->prepare("UPDATE appointments SET status='Cancelled' WHERE id=? AND user_id=? AND status='Pending'");$stmt->execute([(int)$_POST['id'],$_SESSION['user_id']]);header('Location: my_appointments.php');exit;
}
$stmt=$pdo->prepare("SELECT a.*,d.name AS doctor_name,d.specialization FROM appointments a JOIN doctors d ON a.doctor_id=d.id WHERE a.user_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC");$stmt->execute([$_SESSION['user_id']]);$appointments=$stmt->fetchAll();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My Appointments</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include 'includes/header.php'; ?><main class="container"><h1>My Appointments</h1><?php if(isset($_GET['booked'])):?><div class="alert">Appointment request submitted successfully.</div><?php endif;?><?php if(!$appointments):?><div class="panel">You have no appointments yet. <a href="doctors.php">Find a doctor</a>.</div><?php else:?><div class="table-wrap"><table><tr><th>Doctor</th><th>Specialization</th><th>Date</th><th>Time</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php foreach($appointments as $a):?><tr><td><?=htmlspecialchars($a['doctor_name'])?></td><td><?=htmlspecialchars($a['specialization'])?></td><td><?=htmlspecialchars($a['appointment_date'])?></td><td><?=htmlspecialchars(substr($a['appointment_time'],0,5))?></td><td><?=htmlspecialchars($a['reason']??'')?></td><td><span class="status <?=htmlspecialchars($a['status'])?>"><?=htmlspecialchars($a['status'])?></span></td><td><?php if($a['status']==='Pending'):?><form method="post" class="inline" onsubmit="return confirm('Cancel this appointment?')"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="small-btn danger">Cancel</button></form><?php else:?>-<?php endif;?></td></tr><?php endforeach;?></table></div><?php endif;?></main><?php include 'includes/footer.php'; ?></body></html>
